test('failed charge; stale answers ignored', async () => {
  const h = await createHost();
  await h.create('a');
  await h.addItem('a');
  await h.place('a');
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'failed');
  assert.deepEqual(await h.order('a'), { status: 'failed', items: 1, charges: 1, refunds: 0 });
  await h.completeEffect(e.id, 'ok');
  assert.equal((await h.order('a'))!.status, 'failed');
  assert.equal((await h.cancel('a')).ok, false);
});

