import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const charge = async (h: Awaited<ReturnType<typeof createHost>>, order: string, outcome: 'ok' | 'failed') => {
  const effects = (await h.pendingEffects()).filter((e) => e.from === order);
  assert.equal(effects.length, 1);
  await h.completeEffect(effects[0].id, outcome);
};

test('happy path: create, fill, place, pay, ship', async () => {
  const h = await createHost();
  assert.deepEqual(await h.order('a'), null);
  assert.deepEqual(await h.create('a'), { ok: true });
  assert.equal((await h.create('a')).ok, false);
  for (let i = 0; i < 3; i++) assert.equal((await h.addItem('a')).ok, true);
  assert.equal((await h.addItem('a')).ok, false);
  assert.equal((await h.removeItem('a')).ok, true);
  assert.equal((await h.ship('a')).ok, false);
  assert.equal((await h.place('a')).ok, true);
  const [e] = await h.pendingEffects();
  assert.deepEqual({ from: e.from, kind: e.kind, data: e.data }, { from: 'a', kind: 'payment.charge', data: { amount: 2 } });
  assert.deepEqual(await h.order('a'), { status: 'placed', items: 2, charges: 1, refunds: 0 });
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.place('a')).ok, false);
  assert.equal((await h.addItem('a')).ok, false);
  await h.completeEffect(e.id, 'ok');
  assert.deepEqual(await h.pendingEffects(), []);
  assert.equal((await h.order('a'))!.status, 'paid');
  assert.equal((await h.ship('a')).ok, true);
  assert.deepEqual(await h.order('a'), { status: 'shipped', items: 2, charges: 1, refunds: 0 });
  for (const cmd of ['addItem', 'removeItem', 'place', 'ship', 'cancel'] as const) {
    assert.equal((await h[cmd]('a')).ok, false);
  }
});

test('unknown order refused', async () => {
  const h = await createHost();
  for (const cmd of ['addItem', 'removeItem', 'place', 'ship', 'cancel'] as const) {
    const r = await h[cmd]('x');
    assert.equal(r.ok, false);
  }
  assert.equal(await h.order('x'), null);
});

test('empty draft cannot be placed; draft cancel has no refund', async () => {
  const h = await createHost();
  await h.create('a');
  assert.equal((await h.removeItem('a')).ok, false);
  assert.equal((await h.place('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, true);
  assert.deepEqual(await h.order('a'), { status: 'cancelled', items: 0, charges: 0, refunds: 0 });
  assert.equal((await h.cancel('a')).ok, false);
});

test('paid cancel refunds once, no pending refund', async () => {
  const h = await createHost();
  await h.create('a');
  await h.addItem('a');
  await h.place('a');
  await charge(h, 'a', 'ok');
  assert.equal((await h.cancel('a')).ok, true);
  assert.deepEqual(await h.order('a'), { status: 'cancelled', items: 1, charges: 1, refunds: 1 });
  assert.deepEqual(await h.pendingEffects(), []);
  assert.equal((await h.ship('a')).ok, false);
});

test('failed charge; stale answers ignored', async () => {
  const h = await createHost();
  await h.create('a');
  await h.addItem('a');
  await h.place('a');
  const [e] = await h.pendingEffects();
