1	'use strict';
2	
3	// SAM v2 strict spec of one order's stateful core in src/host.impl.ts.
4	// status 'none' is an order id never created. pendingCharges counts the
5	// order's charge effects not yet completed; CHARGE_OK / CHARGE_FAILED are
6	// completeEffect() on that pending charge, STALE_ANSWER is completeEffect()
7	// on an id that is not (or no longer) pending.
8	
9	const { createInstance } = require('@cognitive-fab/sam-pattern');
10	
11	const instance = createInstance({ strict: true, hasAsyncActions: false });
12	
13	const MAX_ITEMS = 3;
14	const MAX_CHARGES = 2;
15	const INITIAL_STATE = { status: 'none', items: 0, charges: 0, refunds: 0, pendingCharges: 0 };
16	
17	const intent = () => ({ action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] });
18	
19	const control = instance({
20	  initialState: { ...INITIAL_STATE },
21	  component: {
22	    modelShape: {
23	      status: { type: 'string' },
24	      items: { type: 'number' },
25	      charges: { type: 'number' },
26	      refunds: { type: 'number' },
27	      pendingCharges: { type: 'number' },
28	    },
29	    actions: {
30	      CREATE: intent(),
31	      ADD_ITEM: intent(),
32	      REMOVE_ITEM: intent(),
33	      PLACE: intent(),
34	      SHIP: intent(),
35	      CANCEL: intent(),
36	      CHARGE_OK: intent(),
37	      CHARGE_FAILED: intent(),
38	      STALE_ANSWER: intent(),
39	      RETRY_PAYMENT: intent(),
40	    },
41	    acceptors: {
42	      CREATE: (model) => (proposal, { reject, next, unchanged }) => {
43	        if (model.status !== 'none') return reject('order-exists');
44	        next.status = 'draft';
45	        unchanged('items', 'charges', 'refunds', 'pendingCharges');
46	      },
47	      ADD_ITEM: (model) => (proposal, { reject, next, unchanged }) => {
48	        if (model.status === 'none') return reject('unknown-order');
49	        if (model.status !== 'draft') return reject('not-a-draft');
50	        if (model.items >= MAX_ITEMS) return reject('draft-full');
51	        next.items = model.items + 1;
52	        unchanged('status', 'charges', 'refunds', 'pendingCharges');
53	      },
54	      REMOVE_ITEM: (model) => (proposal, { reject, next, unchanged }) => {
55	        if (model.status === 'none') return reject('unknown-order');
56	        if (model.status !== 'draft') return reject('not-a-draft');
57	        if (model.items <= 0) return reject('draft-empty');
58	        next.items = model.items - 1;
59	        unchanged('status', 'charges', 'refunds', 'pendingCharges');
60	      },
61	      PLACE: (model) => (proposal, { reject, next, unchanged }) => {
62	        if (model.status === 'none') return reject('unknown-order');
63	        if (model.status !== 'draft') return reject('not-a-draft');
64	        if (model.items < 1) return reject('draft-empty');
65	        next.status = 'placed';
66	        next.charges = model.charges + 1;
67	        next.pendingCharges = model.pendingCharges + 1;
68	        unchanged('items', 'refunds');
69	      },
70	      SHIP: (model) => (proposal, { reject, next, unchanged }) => {
71	        if (model.status === 'none') return reject('unknown-order');
72	        if (model.status !== 'paid') return reject('not-paid');
73	        next.status = 'shipped';
