'use strict';

// SAM v2 strict spec of one order's stateful core in src/host.impl.ts.
// status 'none' is an order id never created. pendingCharges counts the
// order's charge effects not yet completed; CHARGE_OK / CHARGE_FAILED are
// completeEffect() on that pending charge, STALE_ANSWER is completeEffect()
// on an id that is not (or no longer) pending.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const MAX_ITEMS = 3;
const MAX_CHARGES = 2;
const INITIAL_STATE = { status: 'none', items: 0, charges: 0, refunds: 0, pendingCharges: 0 };

const intent = () => ({ action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] });

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      status: { type: 'string' },
      items: { type: 'number' },
      charges: { type: 'number' },
      refunds: { type: 'number' },
      pendingCharges: { type: 'number' },
    },
    actions: {
      CREATE: intent(),
      ADD_ITEM: intent(),
      REMOVE_ITEM: intent(),
      PLACE: intent(),
      SHIP: intent(),
      CANCEL: intent(),
      CHARGE_OK: intent(),
      CHARGE_FAILED: intent(),
      STALE_ANSWER: intent(),
      RETRY_PAYMENT: intent(),
    },
    acceptors: {
      CREATE: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status !== 'none') return reject('order-exists');
        next.status = 'draft';
        unchanged('items', 'charges', 'refunds', 'pendingCharges');
      },
      ADD_ITEM: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status === 'none') return reject('unknown-order');
        if (model.status !== 'draft') return reject('not-a-draft');
        if (model.items >= MAX_ITEMS) return reject('draft-full');
        next.items = model.items + 1;
        unchanged('status', 'charges', 'refunds', 'pendingCharges');
      },
      REMOVE_ITEM: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status === 'none') return reject('unknown-order');
        if (model.status !== 'draft') return reject('not-a-draft');
        if (model.items <= 0) return reject('draft-empty');
        next.items = model.items - 1;
        unchanged('status', 'charges', 'refunds', 'pendingCharges');
      },
      PLACE: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status === 'none') return reject('unknown-order');
        if (model.status !== 'draft') return reject('not-a-draft');
        if (model.items < 1) return reject('draft-empty');
        next.status = 'placed';
        next.charges = model.charges + 1;
        next.pendingCharges = model.pendingCharges + 1;
        unchanged('items', 'refunds');
      },
      SHIP: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status === 'none') return reject('unknown-order');
        if (model.status !== 'paid') return reject('not-paid');
        next.status = 'shipped';
        unchanged('items', 'charges', 'refunds', 'pendingCharges');
      },
      CANCEL: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status === 'none') return reject('unknown-order');
        if (model.status === 'draft') {
          next.status = 'cancelled';
          unchanged('items', 'charges', 'refunds', 'pendingCharges');
          return;
        }
        if (model.status === 'paid') {
          next.status = 'cancelled';
          next.refunds = model.refunds + 1;
          unchanged('items', 'charges', 'pendingCharges');
          return;
        }
        if (model.status === 'placed') {
          next.status = 'cancelling';
          unchanged('items', 'charges', 'refunds', 'pendingCharges');
          return;
        }
        return reject('order-' + model.status);
      },
      CHARGE_OK: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.pendingCharges < 1) return reject('no-pending-charge');
        next.pendingCharges = model.pendingCharges - 1;
        if (model.status === 'cancelling') {
          next.status = 'cancelled';
          next.refunds = model.refunds + 1;
          unchanged('items', 'charges');
          return;
        }
        if (model.status === 'placed') next.status = 'paid';
        else unchanged('status');
        unchanged('items', 'charges', 'refunds');
      },
      CHARGE_FAILED: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.pendingCharges < 1) return reject('no-pending-charge');
        next.pendingCharges = model.pendingCharges - 1;
        if (model.status === 'cancelling') next.status = 'cancelled';
        else if (model.status === 'placed') next.status = model.charges < MAX_CHARGES ? 'declined' : 'failed';
        else unchanged('status');
        unchanged('items', 'charges', 'refunds');
      },
      RETRY_PAYMENT: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status === 'none') return reject('unknown-order');
        if (model.status !== 'declined') return reject('not-declined');
        next.status = 'placed';
        next.charges = model.charges + 1;
        next.pendingCharges = model.pendingCharges + 1;
        unchanged('items', 'refunds');
      },
      STALE_ANSWER: (model) => (proposal, { reject }) => reject('not-pending'),
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  CREATE: (data = {}) => intents.CREATE(data),
  ADD_ITEM: (data = {}) => intents.ADD_ITEM(data),
  REMOVE_ITEM: (data = {}) => intents.REMOVE_ITEM(data),
  PLACE: (data = {}) => intents.PLACE(data),
  SHIP: (data = {}) => intents.SHIP(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
  CHARGE_OK: (data = {}) => intents.CHARGE_OK(data),
  CHARGE_FAILED: (data = {}) => intents.CHARGE_FAILED(data),
  STALE_ANSWER: (data = {}) => intents.STALE_ANSWER(data),
  RETRY_PAYMENT: (data = {}) => intents.RETRY_PAYMENT(data),
};

module.exports = { instance, init, actions, getState, setState };

