// Rules the brief requires of one order.
const TERMINAL = ['shipped', 'cancelled', 'failed'];
const same = (a, b) => Object.keys(a).every((k) => a[k] === b[k]);

export const stateInvariants = [
  { name: 'items-in-range', pred: (s) => s.items >= 0 && s.items <= 3 },
  { name: 'charged-at-most-twice', pred: (s) => s.charges <= 2 },
  { name: 'refunded-at-most-once', pred: (s) => s.refunds <= 1 },
  { name: 'refund-only-after-charge', pred: (s) => s.refunds === 0 || s.charges >= 1 },
  { name: 'refund-only-when-cancelled', pred: (s) => s.refunds === 0 || s.status === 'cancelled' },
  { name: 'uncreated-order-is-blank', pred: (s) => s.status !== 'none' || (s.items === 0 && s.charges === 0 && s.refunds === 0 && s.pendingCharges === 0) },
  { name: 'draft-never-charged', pred: (s) => s.status !== 'draft' || s.charges === 0 },
  { name: 'charged-when-past-draft', pred: (s) => !['placed', 'paid', 'shipped', 'cancelling', 'declined', 'failed'].includes(s.status) || s.charges >= 1 },
  { name: 'charged-order-has-items', pred: (s) => s.charges === 0 || s.items >= 1 },
  { name: 'pending-charge-iff-payment-in-progress', pred: (s) => (s.pendingCharges === 1) === ['placed', 'cancelling'].includes(s.status) && s.pendingCharges <= 1 },
  { name: 'declined-after-exactly-one-charge', pred: (s) => s.status !== 'declined' || s.charges === 1 },
  { name: 'failed-after-two-charges', pred: (s) => s.status !== 'failed' || s.charges === 2 },
  { name: 'shipped-only-when-paid-unrefunded', pred: (s) => s.status !== 'shipped' || (s.charges >= 1 && s.refunds === 0) },
];

export const transitionInvariants = [
  { name: 'terminal-accepts-nothing', pred: (pre, a, d, post) => !TERMINAL.includes(pre.status) || same(pre, post) },
  { name: 'declined-accepts-only-retry', pred: (pre, a, d, post) => pre.status !== 'declined' || a === 'RETRY_PAYMENT' || same(pre, post) },
  { name: 'cancelling-accepts-only-the-answer', pred: (pre, a, d, post) => pre.status !== 'cancelling' || ['CHARGE_OK', 'CHARGE_FAILED'].includes(a) || same(pre, post) },
  { name: 'cancelling-answer-cancels', pred: (pre, a, d, post) => !(pre.status === 'cancelling' && ['CHARGE_OK', 'CHARGE_FAILED'].includes(a)) || post.status === 'cancelled' },
  { name: 'refund-exactly-when-money-taken-and-cancelled', pred: (pre, a, d, post) => {
    const owed = (a === 'CANCEL' && pre.status === 'paid') || (a === 'CHARGE_OK' && pre.status === 'cancelling');
    return post.refunds === pre.refunds + (owed ? 1 : 0);
  } },
  { name: 'cancel-of-placed-is-cancelling-without-refund', pred: (pre, a, d, post) => !(a === 'CANCEL' && pre.status === 'placed') || (post.status === 'cancelling' && post.refunds === pre.refunds) },
  { name: 'charge-only-on-place-or-retry', pred: (pre, a, d, post) => post.charges === pre.charges || (post.charges === pre.charges + 1 && post.status === 'placed' && ((a === 'PLACE' && pre.status === 'draft' && pre.items >= 1) || (a === 'RETRY_PAYMENT' && pre.status === 'declined'))) },
  { name: 'ship-only-when-paid', pred: (pre, a, d, post) => post.status !== 'shipped' || pre.status === 'shipped' || (a === 'SHIP' && pre.status === 'paid') },
  { name: 'items-frozen-after-draft', pred: (pre, a, d, post) => pre.status === 'draft' || pre.status === 'none' || pre.items === post.items },
